// Firecrawl 응답에서 HTML 추출
const res = $input.first().json;
const html = (res && res.data && (res.data.html || res.data.rawHtml)) || res.html || '';
if (!html) {
  throw new Error('Firecrawl 응답에 HTML이 없습니다. 응답 키: ' + JSON.stringify(Object.keys(res || {})));
}

function stripTags(s) {
  return s
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

const results = [];
// 각 곡 행: <tr class="lst50"> 또는 <tr class="lst100">
const rows = html.match(/<tr[^>]*class="[^"]*lst(?:50|100)[^"]*"[\s\S]*?<\/tr>/g) || [];

for (const row of rows) {
  // 순위 - class="rank " 처럼 뒤에 공백이 붙을 수 있음
  const rankMatch = row.match(/<span class="rank[^"]*"[^>]*>\s*(\d+)\s*<\/span>/);
  const rank = rankMatch ? parseInt(rankMatch[1], 10) : null;

  // 곡제목
  const titleBlock = row.match(/<div class="ellipsis rank01">([\s\S]*?)<\/div>/);
  let title = '';
  if (titleBlock) {
    const aMatch = titleBlock[1].match(/<a[^>]*>([\s\S]*?)<\/a>/);
    title = aMatch ? stripTags(aMatch[1]) : stripTags(titleBlock[1]);
  }

  // 가수 - checkEllipsis 숨김 span 이전까지만 사용 (중복 방지), 협업 가수는 쉼표로 연결
  const artistBlock = row.match(/<div class="ellipsis rank02">([\s\S]*?)<\/div>/);
  let artist = '';
  if (artistBlock) {
    const seg = artistBlock[1].split(/<span class="checkEllipsis"/)[0];
    const aMatches = [...seg.matchAll(/<a[^>]*>([\s\S]*?)<\/a>/g)];
    artist = aMatches.length
      ? aMatches.map(m => stripTags(m[1])).filter(Boolean).join(', ')
      : stripTags(seg);
  }

  if (rank && title) {
    results.push({ json: { '순위': rank, '곡제목': title, '가수': artist } });
  }
}

if (!results.length) {
  throw new Error('차트 행을 파싱하지 못했습니다. 멜론 페이지 구조가 변경되었을 수 있습니다.');
}

// 순위 오름차순 정렬 + 중복 제거
const seen = new Set();
const deduped = [];
for (const r of results.sort((a, b) => a.json['순위'] - b.json['순위'])) {
  if (seen.has(r.json['순위'])) continue;
  seen.add(r.json['순위']);
  deduped.push(r);
}

return deduped;
